import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.ecJ-2P1q.js";const n="/v0.4/assets/version-history.DOQwF2tR.png",u=JSON.parse('{"title":"Version History","description":"","frontmatter":{},"headers":[],"relativePath":"guide/version-history.md","filePath":"guide/version-history.md"}'),r={name:"guide/version-history.md"};function i(h,e,l,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h1><p>Aerini keeps a running history of past saves for every workflow, so you can see what changed, compare against an earlier point, or roll back entirely. This page covers opening that history, the difference between an automatic snapshot and a named one, and what Compare, Restore, and Delete actually do.</p><p>If you haven&#39;t read <a href="./../getting-started/concepts">Concepts</a> yet, do that first for what a workflow and a save are. This page assumes you already know those.</p><p><img src="'+n+'" alt="Version History showing a list of snapshots with compare and restore options"></p><h2 id="opening-version-history" tabindex="-1">Opening Version History <a class="header-anchor" href="#opening-version-history" aria-label="Permalink to &quot;Opening Version History&quot;">​</a></h2><p>Click the clock icon in the toolbar (tooltip: <strong>Version history</strong>). It opens as a panel over the canvas, listing every saved snapshot for the workflow you currently have open, newest first.</p><h2 id="every-save-is-a-snapshot" tabindex="-1">Every save is a snapshot <a class="header-anchor" href="#every-save-is-a-snapshot" aria-label="Permalink to &quot;Every save is a snapshot&quot;">​</a></h2><p>You don&#39;t have to do anything extra to build a history. Every time you save the workflow, whether with <strong>Ctrl+S</strong> (<strong>Cmd+S</strong> on macOS), the <strong>Save</strong> button, or automatically right before a background run starts, Aerini records the canvas as it stood at that moment. These automatic entries show up in the list as <strong>Saved</strong>. If the canvas is identical to the last snapshot already on file, nothing new is recorded, so saving repeatedly with no actual changes doesn&#39;t pad the list with duplicates.</p><p>The top entry in the list carries a <strong>Current</strong> badge whenever it matches what&#39;s on your canvas right now, meaning you have no unsaved changes. A small dot in the panel&#39;s header lights up when you do.</p><h2 id="saving-a-named-snapshot-on-purpose" tabindex="-1">Saving a named snapshot on purpose <a class="header-anchor" href="#saving-a-named-snapshot-on-purpose" aria-label="Permalink to &quot;Saving a named snapshot on purpose&quot;">​</a></h2><p>Automatic snapshots are unlabeled by design; if you want a marker you can find later, type a short note into the <strong>Snapshot message (optional)</strong> field at the top of the panel and click <strong>Save Snapshot</strong>. This captures the canvas exactly as it stands right now, unsaved changes included, without needing you to press Save first. It only refuses if the workflow has never been saved at all yet: save it once, then a named snapshot has something to attach to.</p><p>Once you have more than a handful of entries, a <strong>Filter versions…</strong> box appears above the list so you can search by message or date.</p><h2 id="comparing-a-version-against-your-current-canvas" tabindex="-1">Comparing a version against your current canvas <a class="header-anchor" href="#comparing-a-version-against-your-current-canvas" aria-label="Permalink to &quot;Comparing a version against your current canvas&quot;">​</a></h2><p>Click <strong>Compare</strong> on any entry to see exactly what&#39;s different between that snapshot and whatever is on your canvas right now, not between two arbitrary past versions. The diff panel that opens lists every node and connection that was <strong>Added</strong>, <strong>Removed</strong>, or <strong>Changed</strong>, and for anything changed, the specific fields that differ, old value on the left, new value on the right.</p><h2 id="restoring-a-version" tabindex="-1">Restoring a version <a class="header-anchor" href="#restoring-a-version" aria-label="Permalink to &quot;Restoring a version&quot;">​</a></h2><p>Click <strong>Restore</strong>. Aerini asks you to confirm, since it&#39;s about to overwrite whatever&#39;s on your canvas, then loads that snapshot&#39;s nodes and connections in place of what&#39;s there now. Two things worth knowing:</p><ul><li>Before it restores anything, Aerini automatically saves your current canvas as its own snapshot labeled <strong>Before restore</strong>, so restoring is never a one-way trip: the state you restored <em>from</em> is still in the list afterward.</li><li>Restoring loads the old version onto the canvas but doesn&#39;t save it for you. The workflow shows as having unsaved changes until you save again, so you can double-check it before committing.</li></ul><h2 id="deleting-a-version" tabindex="-1">Deleting a version <a class="header-anchor" href="#deleting-a-version" aria-label="Permalink to &quot;Deleting a version&quot;">​</a></h2><p>Click the <strong>×</strong> on any entry to remove just that one snapshot from the history. Aerini asks you to confirm first: deleting is permanent, and unlike Restore there&#39;s no automatic safety snapshot taken beforehand, since nothing on your canvas is being touched.</p><h2 id="how-much-history-is-kept" tabindex="-1">How much history is kept <a class="header-anchor" href="#how-much-history-is-kept" aria-label="Permalink to &quot;How much history is kept&quot;">​</a></h2><p>Aerini keeps up to 50 snapshots per workflow. Past that, saving a new one automatically drops the oldest to make room; there&#39;s currently no setting to raise or lower that number.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../getting-started/concepts">Concepts</a>, for what a workflow and a save are</li><li><a href="./../getting-started/getting-started">Getting Started</a>, for saving a workflow for the first time</li><li><a href="./background-runs">Background Runs</a>, for how a scheduled or webhook run triggers its own automatic snapshot</li></ul>',23)])])}const v=a(r,[["render",i]]);export{u as __pageData,v as default};
